import { supabase } from './supabase.js';

const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)];
const esc=(value='')=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const fmt=value=>value?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'—';
const uid=()=>crypto.randomUUID();
const defaults={background:'#f3f1e9',contentBackground:'#ffffff',textColor:'#293127',buttonColor:'#343b2d',width:640};
const blockDefaults={
  title:()=>({id:uid(),type:'title',content:'Un nouveau chapitre commence.',align:'left',fontSize:38,margin:12,color:'#293127'}),
  text:()=>({id:uid(),type:'text',content:'Bonjour {{prenom}},\n\nÉcrivez ici votre message.',align:'left',fontSize:16,margin:12,color:'#293127'}),
  button:()=>({id:uid(),type:'button',content:'Découvrir',url:'https://stoa-coaching.fr',align:'left',fontSize:15,margin:18,buttonColor:'#343b2d'}),
  image:()=>({id:uid(),type:'image',url:'',alt:'',align:'center',width:100,radius:12,margin:16}),
  divider:()=>({id:uid(),type:'divider',margin:24}),spacer:()=>({id:uid(),type:'spacer',height:32}),
  quote:()=>({id:uid(),type:'quote',content:'Le savoir comme fondation. La santé comme liberté.',align:'left',fontSize:22,margin:18,color:'#293127'}),
  footer:()=>({id:uid(),type:'footer',content:'STOA · Le savoir comme fondation.\nVous recevez cet email en tant que membre STOA.',align:'center',fontSize:12,margin:30,color:'#73766b'})
};

let user,members=[],campaigns=[],campaign=null,blocks=[],settings={...defaults},saveTimer,lastVariableTarget=null,readOnly=false;
const alert=(message,tone='')=>{const node=$('#email-center-alert');node.hidden=!message;node.textContent=message;node.dataset.tone=tone;if(message)setTimeout(()=>{if(node.textContent===message)node.hidden=true;},6000);};
const statusLabel=value=>({draft:'Brouillon',sending:'En cours',sent:'Envoyé',partial:'Partiel',failed:'Échec'}[value]||value);
const audienceLabel=value=>({all:'Tous les utilisateurs',academy:'Membres Académie',coaching:'Clients Coaching',custom:'Sélection personnalisée'}[value]||value);

function recipientRows(){const audience=$('#email-audience').value,selected=new Set(campaign?.custom_recipient_ids||[]);if(audience==='academy')return members.filter(row=>row.has_academy);if(audience==='coaching')return members.filter(row=>row.has_coaching);if(audience==='custom')return members.filter(row=>selected.has(row.user_id));return members;}
function updateRecipientCount(){const count=recipientRows().length;$('#email-recipient-count').textContent=count;$('#email-confirm-count').textContent=`${count} destinataire${count>1?'s':''}`;return count;}
function showView(name){$$('[data-email-view]').forEach(button=>button.classList.toggle('active',button.dataset.emailView===name));$$('.email-center-view').forEach(view=>view.classList.toggle('active',view.dataset.view===name));scrollTo({top:0,behavior:'smooth'});}

function renderMetrics(){const sent=campaigns.filter(row=>['sent','partial'].includes(row.status)),deliveries=sent.reduce((sum,row)=>sum+Number(row.sent_count||0),0),drafts=campaigns.filter(row=>row.status==='draft').length;$('#email-metrics').innerHTML=[['EMAILS ENVOYÉS',deliveries,'Messages remis à Gmail'],['CAMPAGNES',sent.length,'Campagnes envoyées'],['BROUILLONS',drafts,'À reprendre']].map(([label,value,copy])=>`<article class="glass-panel"><small>${label}</small><strong>${value}</strong><span>${copy}</span></article>`).join('');$('#email-draft-badge').textContent=drafts;}
function campaignRow(row){return `<article class="email-campaign-row"><div><span class="email-status" data-status="${row.status}">${statusLabel(row.status)}</span><strong>${esc(row.name)}</strong><p>${esc(row.subject||'Sans objet')}</p></div><div><span>${audienceLabel(row.audience)}</span><strong>${row.status==='draft'?'—':`${row.sent_count||0}/${row.recipient_count||0}`}</strong><small>${fmt(row.sent_at||row.updated_at)}</small></div><div class="email-row-actions"><button type="button" data-open-campaign="${row.id}">${row.status==='draft'?'Modifier':'Consulter'}</button><button type="button" data-duplicate-campaign="${row.id}">Dupliquer</button>${row.status==='draft'?`<button type="button" data-delete-campaign="${row.id}" aria-label="Supprimer">×</button>`:''}</div></article>`;}
function renderLists(){const sorted=[...campaigns].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at)),drafts=sorted.filter(row=>row.status==='draft'),sent=sorted.filter(row=>row.status!=='draft');$('#email-recent-list').innerHTML=sorted.slice(0,6).map(campaignRow).join('')||'<p class="email-empty">Aucune campagne pour le moment.</p>';$('#email-draft-list').innerHTML=drafts.map(campaignRow).join('')||'<p class="email-empty">Aucun brouillon.</p>';$('#email-sent-list').innerHTML=sent.map(campaignRow).join('')||'<p class="email-empty">Aucun email envoyé.</p>';renderMetrics();}
function renderMembers(){const query=$('#email-member-search').value.trim().toLocaleLowerCase('fr-FR'),selected=new Set(campaign?.custom_recipient_ids||[]),rows=members.filter(row=>`${row.first_name||''} ${row.last_name||''} ${row.username||''} ${row.email}`.toLocaleLowerCase('fr-FR').includes(query));$('#email-member-list').innerHTML=rows.map(row=>`<label><input type="checkbox" value="${row.user_id}" ${selected.has(row.user_id)?'checked':''}><span><strong>${esc(row.first_name||row.username||row.email.split('@')[0])} ${esc(row.last_name||'')}</strong><small>${esc(row.email)}</small></span>${row.has_coaching?'<b>Coaching</b>':''}</label>`).join('')||'<p class="email-empty">Aucun membre trouvé.</p>';updateRecipientCount();}

const blockPreview=block=>{
  const common=`text-align:${block.align||'left'};margin:${Number(block.margin)||0}px 0;color:${block.color||settings.textColor}`;
  if(block.type==='title')return `<h2 contenteditable="${!readOnly}" data-block-content style="${common};font-size:${block.fontSize}px">${esc(block.content)}</h2>`;
  if(block.type==='text')return `<p contenteditable="${!readOnly}" data-block-content style="${common};font-size:${block.fontSize}px">${esc(block.content).replaceAll('\n','<br>')}</p>`;
  if(block.type==='quote')return `<blockquote contenteditable="${!readOnly}" data-block-content style="${common};font-size:${block.fontSize}px">${esc(block.content).replaceAll('\n','<br>')}</blockquote>`;
  if(block.type==='button')return `<div style="${common}"><span class="email-button-preview" contenteditable="${!readOnly}" data-block-content style="font-size:${block.fontSize}px;background:${block.buttonColor||settings.buttonColor}">${esc(block.content)}</span></div>`;
  if(block.type==='image')return block.url?`<img src="${esc(block.url)}" alt="${esc(block.alt||'')}" style="display:block;width:${block.width}%;margin:${block.align==='center'?'0 auto':block.align==='right'?'0 0 0 auto':'0'};border-radius:${block.radius}px">`:'<div class="email-image-placeholder"><span>Image</span><small>Téléversez un visuel</small></div>';
  if(block.type==='divider')return '<hr>';
  if(block.type==='spacer')return `<div class="email-spacer-preview" style="height:${block.height}px"><span>${block.height} px</span></div>`;
  return `<footer contenteditable="${!readOnly}" data-block-content style="${common};font-size:${block.fontSize}px">${esc(block.content).replaceAll('\n','<br>')}</footer>`;
};
function blockProperties(block){
  if(readOnly)return '';
  const alignable=['title','text','button','image','quote','footer'].includes(block.type),sizable=['title','text','button','quote','footer'].includes(block.type),colorable=['title','text','quote','footer'].includes(block.type);
  return `<div class="email-block-properties">${alignable?`<label>Alignement<select data-prop="align"><option value="left" ${block.align==='left'?'selected':''}>Gauche</option><option value="center" ${block.align==='center'?'selected':''}>Centre</option><option value="right" ${block.align==='right'?'selected':''}>Droite</option></select></label>`:''}${sizable?`<label>Taille<input type="number" min="12" max="52" data-prop="fontSize" value="${block.fontSize}"></label>`:''}${colorable?`<label>Couleur<input type="color" data-prop="color" value="${block.color||settings.textColor}"></label>`:''}<label>Marge<input type="number" min="0" max="80" data-prop="margin" value="${block.margin||0}"></label>${block.type==='button'?`<label class="wide">Lien<input type="url" data-prop="url" value="${esc(block.url)}"></label><label>Fond<input type="color" data-prop="buttonColor" value="${block.buttonColor||settings.buttonColor}"></label>`:''}${block.type==='image'?`<label class="wide">Image<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" data-image-upload></label><label class="wide">URL<input type="url" data-prop="url" value="${esc(block.url)}"></label><label>Largeur<input type="number" min="20" max="100" data-prop="width" value="${block.width}"></label><label>Arrondi<input type="number" min="0" max="30" data-prop="radius" value="${block.radius}"></label><label class="wide">Texte alternatif<input data-prop="alt" value="${esc(block.alt||'')}"></label>`:''}${block.type==='spacer'?`<label>Hauteur<input type="number" min="8" max="120" data-prop="height" value="${block.height}"></label>`:''}</div>`;
}
function renderCanvas(){const canvas=$('#email-canvas');canvas.style.background=settings.contentBackground;canvas.style.color=settings.textColor;canvas.style.maxWidth=`${settings.width}px`;if(!blocks.length){canvas.innerHTML='<div class="email-empty-canvas"><span>＋</span><strong>Ajoutez votre premier bloc</strong><p>Construisez l’email dans l’ordre de lecture.</p></div>';return;}canvas.innerHTML=blocks.map((block,index)=>`<article class="email-editor-block" data-block-id="${block.id}"><div class="email-block-top"><span>${block.type}</span>${readOnly?'':`<div><button type="button" data-move-block="up" ${index===0?'disabled':''}>↑</button><button type="button" data-move-block="down" ${index===blocks.length-1?'disabled':''}>↓</button><button type="button" data-remove-block aria-label="Supprimer">×</button></div>`}</div><div class="email-block-render">${blockPreview(block)}</div>${blockProperties(block)}</article>`).join('');}
function syncSettings(){settings={background:$('#email-background').value,contentBackground:$('#email-surface').value,textColor:$('#email-text-color').value,buttonColor:$('#email-button-color').value,width:Number($('#email-width').value)};$('#email-width-output').textContent=`${settings.width} px`;document.querySelector('.email-canvas-frame').style.background=settings.background;renderCanvas();scheduleSave();}
function applySettings(){$('#email-background').value=settings.background||defaults.background;$('#email-surface').value=settings.contentBackground||defaults.contentBackground;$('#email-text-color').value=settings.textColor||defaults.textColor;$('#email-button-color').value=settings.buttonColor||defaults.buttonColor;$('#email-width').value=settings.width||defaults.width;$('#email-width-output').textContent=`${settings.width||defaults.width} px`;document.querySelector('.email-canvas-frame').style.background=settings.background||defaults.background;}

async function saveCampaign({silent=false}={}){if(readOnly)return campaign;clearTimeout(saveTimer);const payload={name:$('#email-campaign-name').value.trim()||'Brouillon sans titre',subject:$('#email-subject').value.trim(),audience:$('#email-audience').value,custom_recipient_ids:campaign?.custom_recipient_ids||[],blocks,settings,status:'draft',created_by:user.id};$('#email-save-state').textContent='Enregistrement…';let result;if(campaign?.id)result=await supabase.from('email_campaigns').update(payload).eq('id',campaign.id).select().single();else result=await supabase.from('email_campaigns').insert(payload).select().single();if(result.error){$('#email-save-state').textContent='Erreur d’enregistrement';if(!silent)alert(result.error.message,'error');return null;}campaign=result.data;const index=campaigns.findIndex(row=>row.id===campaign.id);if(index>=0)campaigns[index]=campaign;else campaigns.unshift(campaign);$('#email-save-state').textContent='Brouillon enregistré';renderLists();return campaign;}
function scheduleSave(){if(readOnly)return;$('#email-save-state').textContent='Modifications en attente…';clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveCampaign({silent:true}),700);}
function newCampaign(){campaign={custom_recipient_ids:[]};blocks=[blockDefaults.title(),blockDefaults.text(),blockDefaults.button(),blockDefaults.footer()];settings={...defaults};readOnly=false;$('#email-campaign-name').value='';$('#email-subject').value='';$('#email-audience').value='all';$('#email-custom-members').hidden=true;$('#email-editor-title').textContent='Nouvel email';$('.email-builder-actions [data-email-test]').hidden=false;$('.email-builder-actions [data-email-send]').hidden=false;applySettings();renderCanvas();updateRecipientCount();showView('editor');$('#email-save-state').textContent='Brouillon non enregistré';}
function openCampaign(id){campaign=structuredClone(campaigns.find(row=>row.id===id));if(!campaign)return;blocks=campaign.blocks||[];settings={...defaults,...(campaign.settings||{})};readOnly=campaign.status!=='draft';$('#email-campaign-name').value=campaign.name;$('#email-subject').value=campaign.subject||'';$('#email-audience').value=campaign.audience;$('#email-custom-members').hidden=campaign.audience!=='custom';$('#email-editor-title').textContent=readOnly?'Email envoyé':campaign.name;$('#email-save-state').textContent=readOnly?`${statusLabel(campaign.status)} · ${fmt(campaign.sent_at)}`:'Brouillon enregistré';$('.email-builder-actions [data-email-test]').hidden=readOnly;$('.email-builder-actions [data-email-send]').hidden=readOnly;applySettings();renderMembers();renderCanvas();showView('editor');}
async function duplicateCampaign(id){const source=campaigns.find(row=>row.id===id);const payload={name:`Copie de ${source.name}`,subject:source.subject,audience:source.audience,custom_recipient_ids:source.custom_recipient_ids,blocks:source.blocks,settings:source.settings,status:'draft',created_by:user.id};const {data,error}=await supabase.from('email_campaigns').insert(payload).select().single();if(error)return alert(error.message,'error');campaigns.unshift(data);renderLists();openCampaign(data.id);}
async function deleteCampaign(id){if(!confirm('Supprimer définitivement ce brouillon ?'))return;const {error}=await supabase.from('email_campaigns').delete().eq('id',id).eq('status','draft');if(error)return alert(error.message,'error');campaigns=campaigns.filter(row=>row.id!==id);renderLists();}

const substitute=(value='')=>String(value).replaceAll('{{prenom}}','Jean').replaceAll('{{nom}}','Dupont').replaceAll('{{email}}','jean@exemple.fr');
function emailHtml(){const blockHtml=blocks.map(block=>{const align=block.align||'left',margin=Number(block.margin)||0,color=block.color||settings.textColor,content=substitute(block.content||'');if(block.type==='title')return `<h1 style="margin:${margin}px 0;color:${color};font:500 ${block.fontSize}px/1.12 Georgia,serif;text-align:${align}">${esc(content)}</h1>`;if(block.type==='text')return `<p style="margin:${margin}px 0;color:${color};font:${block.fontSize}px/1.7 Arial,sans-serif;text-align:${align}">${esc(content).replaceAll('\n','<br>')}</p>`;if(block.type==='quote')return `<blockquote style="margin:${margin}px 0;padding:18px 22px;border-left:3px solid ${settings.buttonColor};background:${settings.background};color:${color};font:${block.fontSize}px/1.55 Georgia,serif;text-align:${align}">${esc(content).replaceAll('\n','<br>')}</blockquote>`;if(block.type==='button')return `<div style="margin:${margin}px 0;text-align:${align}"><a href="${esc(block.url)}" style="display:inline-block;padding:14px 24px;border-radius:8px;background:${block.buttonColor||settings.buttonColor};color:#fff;font:${block.fontSize}px Arial;text-decoration:none">${esc(content)}</a></div>`;if(block.type==='image')return block.url?`<div style="margin:${margin}px 0;text-align:${align}"><img src="${esc(block.url)}" alt="${esc(block.alt||'')}" style="display:block;width:${block.width}%;height:auto;margin:${align==='center'?'0 auto':align==='right'?'0 0 0 auto':'0'};border-radius:${block.radius}px"></div>`:'';if(block.type==='divider')return `<div style="height:1px;margin:${Math.max(12,margin)}px 0;background:#d9d9d0"></div>`;if(block.type==='spacer')return `<div style="height:${block.height}px"></div>`;return `<div style="margin:${Math.max(24,margin)}px 0 0;padding-top:22px;border-top:1px solid #d9d9d0;color:${color};font:${block.fontSize}px/1.6 Arial;text-align:${align}">${esc(content).replaceAll('\n','<br>')}</div>`;}).join('');return `<!doctype html><html><head><meta name="viewport" content="width=device-width"></head><body style="margin:0;background:${settings.background};padding:32px 12px"><div style="max-width:${settings.width}px;margin:0 auto;padding:42px;background:${settings.contentBackground};border-radius:18px">${blockHtml}</div></body></html>`;}
function preview(){const frame=$('#email-preview-frame');frame.srcdoc=emailHtml();$('#email-preview-dialog').showModal();}
async function prepareSend(mode,email=''){if(!$('#email-subject').value.trim())return alert('Ajoutez un objet avant l’envoi.','error');if(!blocks.length)return alert('Ajoutez au moins un bloc.','error');if(!updateRecipientCount()&&mode==='send_campaign')return alert('Aucun destinataire sélectionné.','error');const saved=await saveCampaign();if(!saved)return null;const session=(await supabase.auth.getSession()).data.session;const response=await fetch('/api/email-center-send',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${session?.access_token||''}`},body:JSON.stringify({action:mode,campaignId:saved.id,email})});const data=await response.json();if(!response.ok||data?.error)throw new Error(data?.error||'Envoi impossible.');return data;}

async function uploadImage(input,block){const file=input.files?.[0];if(!file)return;if(file.size>10*1024*1024)return alert('L’image dépasse 10 Mo.','error');$('#email-save-state').textContent='Téléversement de l’image…';const saved=await saveCampaign({silent:true});if(!saved)return;const extension=file.name.split('.').pop()?.toLowerCase()||'jpg',path=`${saved.id}/${Date.now()}-${uid()}.${extension}`;const {error}=await supabase.storage.from('email-assets').upload(path,file,{contentType:file.type,upsert:false});if(error)return alert(error.message,'error');const {data}=supabase.storage.from('email-assets').getPublicUrl(path);block.url=data.publicUrl;renderCanvas();scheduleSave();}

document.addEventListener('click',event=>{const view=event.target.closest('[data-email-view]');if(view&&!view.closest('.email-center-tabs')?.matches('[disabled]'))return showView(view.dataset.emailView);if(event.target.closest('#email-new,[data-new-email]'))return newCampaign();const open=event.target.closest('[data-open-campaign]');if(open)return openCampaign(open.dataset.openCampaign);const duplicate=event.target.closest('[data-duplicate-campaign]');if(duplicate)return duplicateCampaign(duplicate.dataset.duplicateCampaign);const removeCampaign=event.target.closest('[data-delete-campaign]');if(removeCampaign)return deleteCampaign(removeCampaign.dataset.deleteCampaign);const add=event.target.closest('[data-add-block]');if(add){blocks.push(blockDefaults[add.dataset.addBlock]());renderCanvas();scheduleSave();return;}const blockNode=event.target.closest('[data-block-id]'),block=blockNode&&blocks.find(item=>item.id===blockNode.dataset.blockId);if(block){if(event.target.closest('[data-remove-block]')){blocks=blocks.filter(item=>item.id!==block.id);renderCanvas();scheduleSave();return;}const move=event.target.closest('[data-move-block]');if(move){const index=blocks.indexOf(block),next=move.dataset.moveBlock==='up'?index-1:index+1;if(next>=0&&next<blocks.length)[blocks[index],blocks[next]]=[blocks[next],blocks[index]];renderCanvas();scheduleSave();return;}}if(event.target.closest('[data-email-preview]'))return preview();if(event.target.closest('[data-email-test]'))return $('#email-test-dialog').showModal();if(event.target.closest('[data-email-send]')){$('#email-confirm-count').textContent=`${updateRecipientCount()} destinataire${updateRecipientCount()>1?'s':''}`;return $('#email-send-dialog').showModal();}const close=event.target.closest('[data-close-dialog]');if(close)return close.closest('dialog').close();const size=event.target.closest('[data-preview-size]');if(size){$$('[data-preview-size]').forEach(node=>node.classList.toggle('active',node===size));$('.email-preview-shell').classList.toggle('mobile',size.dataset.previewSize==='mobile');return;}const variable=event.target.closest('[data-email-variable]');if(variable){const target=lastVariableTarget||$('#email-subject');if(target.isContentEditable){target.focus();document.execCommand('insertText',false,variable.dataset.emailVariable);}else{const start=target.selectionStart??target.value.length;target.setRangeText(variable.dataset.emailVariable,start,target.selectionEnd??start,'end');target.dispatchEvent(new Event('input',{bubbles:true}));}return;}});
document.addEventListener('focusin',event=>{if(event.target.matches('[contenteditable=true],#email-subject'))lastVariableTarget=event.target;});
$('#email-canvas').addEventListener('input',event=>{const node=event.target.closest('[data-block-id]'),block=node&&blocks.find(item=>item.id===node.dataset.blockId);if(!block)return;if(event.target.matches('[data-block-content]'))block.content=event.target.innerText;scheduleSave();});
$('#email-canvas').addEventListener('change',event=>{const node=event.target.closest('[data-block-id]'),block=node&&blocks.find(item=>item.id===node.dataset.blockId);if(!block)return;if(event.target.matches('[data-image-upload]'))return uploadImage(event.target,block);const prop=event.target.dataset.prop;if(prop){block[prop]=event.target.type==='number'?Number(event.target.value):event.target.value;renderCanvas();scheduleSave();}});
['email-campaign-name','email-subject'].forEach(id=>$('#'+id).addEventListener('input',scheduleSave));
$('#email-audience').addEventListener('change',()=>{$('#email-custom-members').hidden=$('#email-audience').value!=='custom';renderMembers();scheduleSave();});
$('#email-member-search').addEventListener('input',renderMembers);$('#email-member-list').addEventListener('change',event=>{if(!event.target.matches('input[type=checkbox]'))return;const selected=new Set(campaign?.custom_recipient_ids||[]);event.target.checked?selected.add(event.target.value):selected.delete(event.target.value);campaign.custom_recipient_ids=[...selected];updateRecipientCount();scheduleSave();});
['email-background','email-surface','email-text-color','email-button-color','email-width'].forEach(id=>$('#'+id).addEventListener('input',syncSettings));
$('#email-test-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,status=form.querySelector('[role=status]'),button=form.querySelector('[type=submit]');button.disabled=true;status.textContent='Envoi en cours…';try{await prepareSend('test',form.elements.email.value.trim());status.textContent='Email test envoyé.';}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});
$('#email-send-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,status=form.querySelector('[role=status]'),button=form.querySelector('[type=submit]');button.disabled=true;status.textContent='Envoi en cours…';try{const result=await prepareSend('send_campaign');status.textContent=`${result.sent} email(s) envoyé(s)${result.failed?`, ${result.failed} échec(s)`:''}.`;setTimeout(()=>location.reload(),1100);}catch(error){status.textContent=error.message;}finally{button.disabled=false;}});

async function initialize(){user=(await supabase.auth.getSession()).data.session?.user;if(!user){location.replace('/#connexion');return;}const [{data:profile},{data:memberRows,error:memberError},{data:campaignRows,error:campaignError}]=await Promise.all([supabase.from('profiles').select('role').eq('id',user.id).maybeSingle(),supabase.rpc('get_email_center_members'),supabase.from('email_campaigns').select('*').order('updated_at',{ascending:false})]);if(profile?.role!=='admin'||memberError?.code==='42501'){location.replace('/accueil');return;}if(memberError||campaignError)return alert(memberError?.message||campaignError?.message,'error');members=memberRows||[];campaigns=campaignRows||[];renderLists();updateRecipientCount();}
initialize();
